# AUTOGENERATED COPYRIGHT HEADER END
# Creates or updates the comment that lists the tests of a pull request (see test.yml and test-report.py).
# Usage: test-comment.sh get <pull request number>                                  prints the body of the comment, if any
#        test-comment.sh post <pull request number> <head commit of the pull request> <comment file>
# A single comment is kept per pull request, found by the hidden marker on its first line. Nothing is posted if the pull
# request has moved on to another commit, or when the token can not write comments (a pull request from a fork).
# The environment needs GH_TOKEN and GH_REPO.
set -u
marker='<!-- blitzllvm-tests -->'
action="$1"; number="$2"

find_comment() {
	gh api --paginate "repos/${GH_REPO}/issues/${number}/comments" \
		--jq "[.[] | select(.user.type == \"Bot\" and (.body | startswith(\"${marker}\")))][0] | select(. != null) | .id" | head -n1
}

if [ "$action" = "get" ]; then
	id="$(find_comment)"
	[ -n "$id" ] && gh api "repos/${GH_REPO}/issues/comments/${id}" --jq .body
	exit 0
fi

sha="$3"; file="$4"

current="$(gh api "repos/${GH_REPO}/pulls/${number}" --jq .head.sha)" || exit 0
if [ "$current" != "$sha" ]; then
	echo "The pull request moved on to ${current}, skipping."
	exit 0
fi

id="$(find_comment)"

if [ -n "$id" ]; then
	gh api -X PATCH "repos/${GH_REPO}/issues/comments/${id}" -F body=@"$file" > /dev/null || echo "::warning::Could not update the test comment (a fork has no write access)."
else
	gh api -X POST "repos/${GH_REPO}/issues/${number}/comments" -F body=@"$file" > /dev/null || echo "::warning::Could not create the test comment (a fork has no write access)."
fi
exit 0
